import { describe, expect, it } from "vitest";
import { createApp, type App } from "../src/app.ts";
import { transaction } from "../src/db.ts";

const fixedClock = () => new Date("2026-10-01T08:00:00Z");

function createCoupon(app: App, overrides: Record<string, unknown> = {}): void {
  const res = app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    ...overrides,
  });
  if (res.status !== 201) throw new Error(`coupon setup failed: ${JSON.stringify(res.body)}`);
}

function createOrder(app: App, amountCents = 12000): number {
  const res = app.request("POST", "/orders", { customer: "alice", amountCents });
  return (res.body as any).id as number;
}

describe("apply coupon", () => {
  it("applies a fixed-amount coupon", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { type: "FIXED", value: 2000 });
    const id = createOrder(app, 12000);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({
      couponCode: "SAVE20",
      discountCents: 2000,
      finalAmountCents: 10000,
      status: "PENDING",
    });
  });

  it("applies a percentage coupon", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { type: "PERCENT", value: 20 });
    const id = createOrder(app, 12000);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.body).toMatchObject({ discountCents: 2400, finalAmountCents: 9600 });
  });

  it("caps a percentage discount and never exceeds the amount", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { type: "PERCENT", value: 50, maxDiscountCents: 1000 });
    const capped = createOrder(app, 10000);
    expect(app.request("POST", `/orders/${capped}/apply-coupon`, { couponCode: "SAVE20" }).body).toMatchObject({
      discountCents: 1000,
      finalAmountCents: 9000,
    });

    createCoupon(app, { code: "BIG", type: "FIXED", value: 5000 });
    const small = createOrder(app, 3000);
    expect(app.request("POST", `/orders/${small}/apply-coupon`, { couponCode: "BIG" }).body).toMatchObject({
      discountCents: 3000,
      finalAmountCents: 0,
    });
  });

  it("returns 404 for an unknown order", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app);
    const res = app.request("POST", "/orders/99/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("ORDER_NOT_FOUND");
  });

  it("returns 404 for an unknown coupon", () => {
    const app = createApp({ clock: fixedClock });
    const id = createOrder(app);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "NOPE" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("COUPON_NOT_FOUND");
  });

  it("rejects a missing coupon code", () => {
    const app = createApp({ clock: fixedClock });
    const id = createOrder(app);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, {});
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("INVALID_REQUEST");
  });

  it("rejects a non-pending order", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app);
    const id = createOrder(app);
    app.request("POST", `/orders/${id}/pay`);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("rejects a second coupon on the same order", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app);
    const id = createOrder(app);
    app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_ALREADY_APPLIED");
  });

  it("rejects a disabled coupon", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { status: "DISABLED" });
    const id = createOrder(app);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_DISABLED");
  });

  it("rejects a coupon that is not yet valid", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { validFrom: "2026-11-01T00:00:00Z", validUntil: "2027-01-01T00:00:00Z" });
    const id = createOrder(app);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_NOT_YET_VALID");
  });

  it("rejects an expired coupon", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { validFrom: "2025-01-01T00:00:00Z", validUntil: "2026-01-01T00:00:00Z" });
    const id = createOrder(app);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_EXPIRED");
  });

  it("enforces the usage limit", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { usageLimit: 1 });
    const first = createOrder(app);
    const second = createOrder(app);
    expect(app.request("POST", `/orders/${first}/apply-coupon`, { couponCode: "SAVE20" }).status).toBe(200);
    const res = app.request("POST", `/orders/${second}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_USAGE_LIMIT_REACHED");
    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
  });

  it("enforces the minimum order amount", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { minAmountCents: 5000 });
    const id = createOrder(app, 4000);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_MIN_AMOUNT_NOT_MET");
  });

  it("records the redemption in a transaction", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app);
    const id = createOrder(app);
    app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    const rows = app.db.prepare("SELECT * FROM coupon_redemptions").all() as any[];
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({ order_id: id, coupon_code: "SAVE20", discount_cents: 2400 });
  });
});

describe("transaction", () => {
  it("rolls back when the callback throws", () => {
    const app = createApp({ clock: fixedClock });
    const id = createOrder(app);
    expect(() =>
      transaction(app.db, () => {
        app.db.prepare("UPDATE orders SET discount_cents = 1 WHERE id = ?").run(id);
        throw new Error("boom");
      }),
    ).toThrow("boom");
    expect(app.db.prepare("SELECT discount_cents FROM orders WHERE id = ?").get(id)).toMatchObject({
      discount_cents: 0,
    });
  });
});
